"""Publish measured shared-storage layouts, simulations and honest capacity boundary."""
from pathlib import Path
import hashlib,json,re,subprocess,datetime,zipfile
R=Path(__file__).resolve().parents[1];B=R/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return p.relative_to(R).as_posix()
def main():
 items=[('gf180_shared_analog_memory_3t_v2','screen_gf180_shared_memory_3t_v2_three_cases.py','_three_native_5ms_src','native_compact_memory_write_hold_read_observed'),('gf180_shared_memory_bank8x8_v2','screen_gf180_shared_bank8x8_v2_native_sequence_slew_v2.py','_native_select_write_hold_read_src','native_shared_bank_sequence_observed'),('gf180_shared_underplate_3t_v2','screen_gf180_shared_underplate_3t_v2_three_cases.py','_three_native_5ms_src','native_compact_memory_write_hold_read_observed'),('gf180_underplate_bank8x8_v3','screen_gf180_underplate_bank8x8_v3_native_sequence.py','_native_select_write_hold_read_src','native_shared_bank_sequence_observed'),('gf180_underplate_biased_bank8x8_v1','screen_gf180_underplate_biased_bank8x8_v1_native_sequence.py','_native_select_write_hold_read_src','native_shared_bank_sequence_observed')]
 reports=[]
 for cell,script,stem,gate in items:
  rp=B/'results'/(cell+stem+sha(R/'scripts'/script)[:12]+'.json');rr=json.loads(rp.read_text());assert rr['module_simulation_completed'];reports.append(rp)
  latest=max(B.glob('assembly/article_module_catalog_v*.json'),key=lambda p:int(re.search(r'_v(\d+)',p.name)[1]));rev=int(re.search(r'_v(\d+)',latest.name)[1])+1
  subprocess.run(['python',str(R/'scripts/publish_gf180_characterization_assembly_20261011_v2.py'),'--cell',cell,'--revision',str(rev),'--report',rel(rp),'--role','shared_analog_storage_optimization','--gate',gate,'--note','Single-NFET write within1.0-1.4V,3.3V wordline; local read isolation retained. Actual shared row/column wiring and MIM overlap where present. Article prototype evidence; uncalibrated read offsets and external controls/references remain. Fullchip incomplete.'],check=True)
 cell=items[-1][0];sp=R/'scripts/screen_gf180_underplate_biased_bank8x8_v1_native_50ms_sequence.py';ret=B/'results'/(cell+'_native_50ms_select_write_hold_read_src'+sha(sp)[:12]+'.json');rr=json.loads(ret.read_text());assert rr['module_simulation_completed']
 baseline=B/'layout/gf180_compact_memory_bank8x8_v1/qualification.json';old=json.loads(baseline.read_text());area=lambda q:(q['bbox_um'][2]-q['bbox_um'][0])*(q['bbox_um'][3]-q['bbox_um'][1]);old_area=area(old);versions=[]
 for c,_,_,_ in items:
  qp=B/'layout'/c/'qualification.json';q=json.loads(qp.read_text());n=q['native_mim_count'];versions.append(dict(cell=c,area_um2=area(q),state_slots=n,area_per_slot_um2=area(q)/n,mos_count=q['mos_count'],source_GDS_DRC_zero_LVS_unique=True))
 latest=B/'assembly'/f'article_module_catalog_v{rev}.json';cap=B/'assembly/full_capacity_storage_gds_v2/capacity_assembly.json';cp=json.loads(cap.read_text());five=json.loads(reports[-1].read_text())
 out=B/'results/gf180_shared_storage_area_milestone_v1.json';assert not out.exists();payload=dict(baseline_cell=old['cell'],baseline_bank_area_um2=old_area,layouts=versions,core_bank_reduction_fraction=1-versions[-2]['area_um2']/old_area,bank_with_native_bias_reduction_fraction=1-versions[-1]['area_um2']/old_area,selected_storage_candidate=cell,simulation_5ms_max_write_error_v=five['max_write_error_v'],simulation_5ms_max_hold_excursion_v=five['max_hold_excursion_v'],simulation_5ms_max_final_read_state_change_v=five['max_read_disturbance_v'],simulation_50ms_max_hold_excursion_v=rr['max_hold_excursion_v'],simulation_50ms_max_final_read_state_change_v=rr['max_read_disturbance_v'],storage_capacity_projection_mm2=cp['total_bank_geometry_area_mm2'],active_states=cp['logical_active_analog_nodes'],physical_slots=cp['physical_storage_slots'],shared_circuitry=['8data columns','8read columns','8read-current sinks for64states','1diode bias master','8write and8read row wordlines','power/reference buses'],retained_local_circuitry='one NFET write-access,one source-follower,one read-select,one50fF MIM perstate',limitations='Typical27C/noise-off,limited1.0-1.4V window and ideal external row/address/data/master-reference fixtures. Native column mirror and wiring included, decoder/write drivers/global programming/read offset calibration excluded. Write error17.31mV remains; nominal20mV local gate is not model precision acceptance. Baseline4T10ns and revised3T100ns wordline slew differ; measured area comparison is valid, but no isolated causal improvement of electrical precision is claimed. Fully resident54.6millionstate architecture is still large; updated GDS is storage-only, not fullchip or manufacturable die.',next_action='Dense shared row-decoder/write drivers, analog read calibration and connected compute tile; then global physical assembly and service/accuracy characterization.',full_chip_layout_complete=False,sha256={rel(p):sha(p) for p in [Path(__file__),baseline,*reports,ret,cap,latest]})
 out.write_text(json.dumps(payload,indent=2)+'\n')
 docs=[R/'docs'/n for n in ['AGENTS.md','ACTIVE_TASKS.md','ARCHITECTURE.md','DECISIONS.md','RESULTS.md','PROGRESS.md','project_spec.yaml']];stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');archive=B/'documentation_history'/('project_docs_before_shared_storage_summary_'+stamp+'.zip')
 with zipfile.ZipFile(archive,'x',zipfile.ZIP_DEFLATED) as z:
  for p in docs:z.writestr(rel(p),p.read_bytes())
 archive.with_suffix('.json').write_text(json.dumps({'sha256':sha(archive),'files':{rel(p):sha(p) for p in docs}},indent=2))
 p=R/'docs/ACTIVE_TASKS.md';raw=p.read_bytes();raw=re.sub(rb'20 reusable module sets and52 characterization assemblies; catalog revision\d+',b'20 reusable module sets and57 characterization assemblies; catalog revision75',raw);raw=re.sub(rb'\| Storage \|[^\r\n]*',b'| Storage | New3T/50fF bank places transistors under MIM and shares native column bias; core49.3% smaller, bank with bias40.3% smaller; physical checks and5ms/50ms sequences complete |',raw);raw=re.sub(rb'\| Live jobs \|[^\r\n]*',b'| Live jobs | None; all shared-storage runs terminal and preserved |',raw);raw=raw.replace(b'1. Complete connected analog compute/control interfaces',b'1. Integrate dense shared row decoder/write drivers and calibrated analog read interfaces, then complete connected analog compute/control interfaces');raw=raw.replace(b'full_capacity_storage_gds_v1/capacity_assembly.json`;54,630,400 active identities,866,080 actual8x8 banks,14,545.65mm2 bank geometry',b'full_capacity_storage_gds_v2/capacity_assembly.json`;54,630,400 active identities,866,080 actual8x8 banks,8,676.37mm2 including native shared column bias (previous4T bank14,545.65mm2)')
 raw+=b'\r\nShared storage milestone: `artifacts/analog_asic/results/gf180_shared_storage_area_milestone_v1.json`. Core8517.056um2/64states; native-bias bank10017.972um2/64states.5ms:write17.31mV,hold6.88mV,final read change2.67mV.50ms:hold6.88mV,final read change2.35mV. Original-float accuracy, permanent parameter retention and complete ASIC remain unaccepted. Local read buffer retained; passive capacitor-to-column read would require qualified destructive sensing/restore. Next:dense row/write periphery and calibrated read into compute tile.\r\n';p.write_bytes(raw)
 p=R/'docs/project_spec.yaml';raw=p.read_bytes();head,tail=raw.split(b'\ndocument:',1);head=re.sub(rb'  live_sessions: [^\r\n]*',b'  live_sessions: []',head,count=1);head=re.sub(rb'  storage_candidate: [^\r\n]*',b'  storage_candidate: underplate_3T_50fF_8x8_native_shared_column_bias_5ms50ms_offset_uncalibrated',head,count=1);head=re.sub(rb'  evidence: [^\r\n]*',b'  evidence: '+rel(out).encode(),head,count=1);head=re.sub(rb'    status: [^\r\n]*',b'    status: 20_modules_57_assemblies_shared_storage_optimized_fullchip_incomplete',head,count=1);head=re.sub(rb'    next_action: [^\r\n]*',b'    next_action: dense_shared_row_write_periphery_and_read_calibration_then_connected_compute_tile',head,count=1);head=head.replace(b'  area_scope:\r\n',b'  area_scope:\r\n    shared_storage_capacity_projection_mm2: 8676.36518976\r\n    shared_storage_report: '+rel(out).encode()+b'\r\n');p.write_bytes(head+b'\ndocument:'+tail)
 note=('\n\nShared storage optimization -2026-10-11: actual3T/50fF bank with transistors below MIM, shared row/column buses and9MOS column mirror. Bank core8517.056um2 vs16794.808um2 (-49.3%); with native bias10017.972um2 (-40.3% against old bank excluding bias). Source/GDS fullDRC0, independentLVS, realLEF and2103 nonnegative native cap branches.5ms and50ms64-state sequences complete; maxwrite17.31mV,hold6.88mV,finalreadchange2.67/2.35mV. Source-follower offset uncalibrated. Single-NFET write range1.0-1.4V; do not assume arbitrary analog voltage range. Full state-capacity atlasv2 projects8676.37mm2 storage plus native bias, excluding decoder/write drivers/global compute/wiring; fullchip incomplete. Local buffered reads remain to preserve independent analog charge. See `'+rel(out)+'`. Next:dense shared row/write circuitry, read calibration and connected compute tile.\n')
 for name in ['RESULTS.md','DECISIONS.md','ARCHITECTURE.md','PROGRESS.md']:
  p=R/'docs'/name;p.write_bytes(p.read_bytes()+note.encode())
 print(json.dumps({k:v for k,v in payload.items() if k not in ['sha256','layouts']},indent=2))
if __name__=='__main__':main()
